import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long sum = 0, sqSum = 0;
        for (int i = 0; i < n; i++) {
            long x = sc.nextLong();
            sum += x;
            sqSum += x * x;
        }
        long expSum = n * (n + 1) / 2;
        long expSq = n * (n + 1) * (2 * n + 1) / 6;
        long diff = expSum - sum; // missing - dup
        long sqDiff = expSq - sqSum; // missing^2 - dup^2
        long sumMD = sqDiff / diff; // missing + dup
        long missing = (diff + sumMD) / 2;
        long dup = missing - diff;
        System.out.println(missing + " " + dup);
    }
}

