import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long d1 = 0, d2 = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long val = sc.nextLong();
                if (i == j) d1 += val;
                if (i + j == n - 1) d2 += val;
            }
        }
        System.out.println(Math.abs(d1 - d2));
    }
}
